(function(global){
  var JsPDF=global.jspdf&&global.jspdf.jsPDF;if(!JsPDF)return;
  JsPDF.prototype.autoTable=function(options){
    options=options||{};var y=Number(options.startY||40);var x=20;var rowHeight=10;var pageBottom=560;var margin=(options.margin&&options.margin.left)||20;var headers=options.head||[];var body=options.body||[];var rows=headers.concat(body);
    rows.forEach((row,index)=>{if(y>pageBottom){this.addPage();y=30;if(headers.length&&index>=headers.length){headers.forEach(h=>{this.setFontSize(6);this.text(h.join(" | "),margin,y);y+=rowHeight})}}this.setFontSize(index<headers.length?7:6);this.text((row||[]).map(v=>String(v==null?"":v)).join(" | "),margin,y);y+=rowHeight});
    this.lastAutoTable={finalY:y};return this;
  };
})(window);
